export const SOLUTIONS = {"13-1":{"ch":13,"entry":"stars_game.py","mode":"run","reason":null,"files":{"images/star.png":{"b64":""},"images/star_original.png":{"b64":""},"settings.py":"class Settings:\n    \"\"\"A class to store all settings for the game.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game's settings.\"\"\"\n        # Screen settings\n        self.screen_width = 1200\n        self.screen_height = 800\n        self.bg_color = (50, 50, 50)","star.py":"import pygame\nfrom pygame.sprite import Sprite\n \nclass Star(Sprite):\n    \"\"\"A class to represent a single star.\"\"\"\n\n    def __init__(self, stars_game):\n        \"\"\"Initialize the star and set its starting position.\"\"\"\n        super().__init__()\n        self.screen = stars_game.screen\n\n        # Load the star image and set its rect attribute.\n        #   Star image from: https://opengameart.org/content/star\n        #   License: public domain\n        self.image = pygame.image.load('images/star.png')\n        self.rect = self.image.get_rect()\n\n        # Start each new star near the top left of the screen.\n        self.rect.x = self.rect.width\n        self.rect.y = self.rect.height\n\n        # Note: Since the stars won't be moving, we don't need to track\n        #  their exact position.\n","stars_game.py":"import sys\n\nimport pygame\n\nfrom settings import Settings\nfrom star import Star\n\n\nclass StarsGame:\n    \"\"\"Overall class to manage game assets and behavior.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game, and create game resources.\"\"\"\n        pygame.init()\n        self.clock = pygame.time.Clock()\n        self.settings = Settings()\n\n        self.screen = pygame.display.set_mode(\n                (self.settings.screen_width, self.settings.screen_height))\n        pygame.display.set_caption(\"Stars\")\n\n        self.stars = pygame.sprite.Group()\n        self._create_stars()\n\n    def run_game(self):\n        \"\"\"Start the main loop for the game.\"\"\"\n        while True:\n            self._check_events()\n            self._update_screen()\n            self.clock.tick(60)\n\n    def _check_events(self):\n        \"\"\"Respond to keypresses and mouse events.\"\"\"\n        for event in pygame.event.get():\n            if event.type == pygame.QUIT:\n                sys.exit()\n            elif event.type == pygame.KEYDOWN:\n                self._check_keydown_events(event)\n\n    def _check_keydown_events(self, event):\n        \"\"\"Respond to keypresses.\"\"\"\n        if event.key == pygame.K_q:\n            sys.exit()\n\n    def _create_stars(self):\n        \"\"\"Create a sky full of stars.\"\"\"\n        # Create a star and keep adding stars until there's no room left.\n        #   Spacing between stars is two star widths.\n        star = Star(self)\n        star_width, star_height = star.rect.size\n\n        current_x, current_y = 2*star_width, 2*star_height\n        while current_y < (self.settings.screen_height - 3 * star_height):\n            while current_x < (self.settings.screen_width - 2 * star_width):\n                self._create_star(current_x, current_y)\n                current_x += 2 * star_width\n\n            # Finished a row; reset x value, and increment y value.\n            current_x = 2 * star_width\n            current_y += 2 * star_height\n\n    def _create_star(self, x_position, y_position):\n        \"\"\"Create a star and place it in the grid.\"\"\"\n        new_star = Star(self)\n        new_star.rect.x = x_position\n        new_star.rect.y = y_position\n        self.stars.add(new_star)\n\n    def _update_screen(self):\n        \"\"\"Update images on the screen, and flip to the new screen.\"\"\"\n        self.screen.fill(self.settings.bg_color)\n        self.stars.draw(self.screen)\n\n        pygame.display.flip()\n\n\nif __name__ == '__main__':\n    # Make a game instance, and run the game.\n    sg = StarsGame()\n    sg.run_game()\n"}},"13-2":{"ch":13,"entry":"stars_game.py","mode":"run","reason":null,"files":{"images/star.png":{"b64":""},"images/star_original.png":{"b64":""},"settings.py":"class Settings:\n    \"\"\"A class to store all settings for the game.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game's settings.\"\"\"\n        # Screen settings\n        self.screen_width = 1200\n        self.screen_height = 800\n        self.bg_color = (50, 50, 50)","star.py":"import pygame\nfrom pygame.sprite import Sprite\n \nclass Star(Sprite):\n    \"\"\"A class to represent a single star.\"\"\"\n\n    def __init__(self, stars_game):\n        \"\"\"Initialize the star and set its starting position.\"\"\"\n        super().__init__()\n        self.screen = stars_game.screen\n\n        # Load the star image and set its rect attribute.\n        #   Star image from: https://opengameart.org/content/star\n        #   License: public domain\n        self.image = pygame.image.load('images/star.png')\n        self.rect = self.image.get_rect()\n\n        # Start each new star near the top left of the screen.\n        self.rect.x = self.rect.width\n        self.rect.y = self.rect.height\n\n        # Note: Since the stars won't be moving, we don't need to track\n        #  their exact position.","stars_game.py":"import sys\nfrom random import randint\n\nimport pygame\n\nfrom settings import Settings\nfrom star import Star\n\n\nclass StarsGame:\n    \"\"\"Overall class to manage game assets and behavior.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game, and create game resources.\"\"\"\n        pygame.init()\n        self.clock = pygame.time.Clock()\n        self.settings = Settings()\n\n        self.screen = pygame.display.set_mode(\n                (self.settings.screen_width, self.settings.screen_height))\n        pygame.display.set_caption(\"Stars\")\n\n        self.stars = pygame.sprite.Group()\n        self._create_stars()\n\n    def run_game(self):\n        \"\"\"Start the main loop for the game.\"\"\"\n        while True:\n            self._check_events()\n            self._update_screen()\n            self.clock.tick(60)\n\n    def _check_events(self):\n        \"\"\"Respond to keypresses and mouse events.\"\"\"\n        for event in pygame.event.get():\n            if event.type == pygame.QUIT:\n                sys.exit()\n            elif event.type == pygame.KEYDOWN:\n                self._check_keydown_events(event)\n\n    def _check_keydown_events(self, event):\n        \"\"\"Respond to keypresses.\"\"\"\n        if event.key == pygame.K_q:\n            sys.exit()\n\n    def _create_stars(self):\n        \"\"\"Create a sky full of stars.\"\"\"\n        # Create a star and keep adding stars until there's no room left.\n        #   Spacing between stars is two star widths.\n        star = Star(self)\n        star_width, star_height = star.rect.size\n\n        current_x, current_y = 2*star_width, 2*star_height\n        while current_y < (self.settings.screen_height - 3 * star_height):\n            while current_x < (self.settings.screen_width - 2 * star_width):\n                self._create_star(current_x, current_y)\n                current_x += 2 * star_width\n\n            # Finished a row; reset x value, and increment y value.\n            current_x = 2 * star_width\n            current_y += 2 * star_height\n\n\n    def _create_star(self, x_position, y_position):\n        \"\"\"Create a star and place it in the grid.\"\"\"\n        # Add a random offset in each direction.\n        new_star = Star(self)\n        new_star.rect.x = x_position + self._get_star_offset()\n        new_star.rect.y = y_position + self._get_star_offset()\n\n        self.stars.add(new_star)\n\n    def _get_star_offset(self):\n        \"\"\"Return a random adjustment to a star's position.\"\"\"\n        offset_size = 15\n        return randint(-1*offset_size, offset_size)\n\n    def _update_screen(self):\n        \"\"\"Update images on the screen, and flip to the new screen.\"\"\"\n        self.screen.fill(self.settings.bg_color)\n        self.stars.draw(self.screen)\n\n        pygame.display.flip()\n\n\nif __name__ == '__main__':\n    # Make a game instance, and run the game.\n    sg = StarsGame()\n    sg.run_game()\n"}},"13-3":{"ch":13,"entry":"raindrops_game.py","mode":"run","reason":null,"files":{"images/raindrop.png":{"b64":""},"raindrop.py":"import pygame\nfrom pygame.sprite import Sprite\n \nclass Raindrop(Sprite):\n    \"\"\"A class to represent a single raindrop.\"\"\"\n\n    def __init__(self, rd_game):\n        \"\"\"Initialize the raindrop and set its starting position.\"\"\"\n        super().__init__()\n        self.screen = rd_game.screen\n        self.settings = rd_game.settings\n\n        # Load the raindrop image and set its rect attribute.\n        #   Raindrop image from: https://commons.wikimedia.org/wiki/File:Antu_raindrop.svg\n        #   License: https://creativecommons.org/licenses/by-sa/3.0/deed.en\n        #   Modified size, and cropped.\n        self.image = pygame.image.load('images/raindrop.png')\n        self.rect = self.image.get_rect()\n\n        # Start each new raindrop near the top left of the screen.\n        self.rect.x = self.rect.width\n        self.rect.y = self.rect.height\n\n        # Store the raindrop's exact vertical position.\n        self.y = float(self.rect.y)\n\n    def update(self):\n        \"\"\"Move the raindrop down the screen.\"\"\"\n        self.y += self.settings.raindrop_speed\n        self.rect.y = self.y\n","raindrops_game.py":"import sys\n\nimport pygame\n\nfrom settings import Settings\nfrom raindrop import Raindrop\n\nclass RaindropsGame:\n    \"\"\"Overall class to manage game assets and behavior.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game, and create game resources.\"\"\"\n        pygame.init()\n        self.clock = pygame.time.Clock()\n        self.settings = Settings()\n\n        self.screen = pygame.display.set_mode(\n                (self.settings.screen_width, self.settings.screen_height))\n        pygame.display.set_caption(\"Raindrops\")\n\n        self.raindrops = pygame.sprite.Group()\n        self._create_drops()\n\n    def run_game(self):\n        \"\"\"Start the main loop for the game.\"\"\"\n        while True:\n            self._check_events()\n            self.raindrops.update()\n            self._update_screen()\n            self.clock.tick(60)\n\n    def _check_events(self):\n        \"\"\"Respond to keypresses and mouse events.\"\"\"\n        for event in pygame.event.get():\n            if event.type == pygame.QUIT:\n                sys.exit()\n            elif event.type == pygame.KEYDOWN:\n                self._check_keydown_events(event)\n\n    def _check_keydown_events(self, event):\n        \"\"\"Respond to keypresses.\"\"\"\n        if event.key == pygame.K_q:\n            sys.exit()\n\n    def _create_drops(self):\n        \"\"\"Create a sky full of raindrops.\"\"\"\n        # Create a drop and keep adding drops until there's no room left.\n        #   Spacing between drops is one drop width.\n        #   Note that the spacing here works reasonably for larger drops.\n        #   If you're working with smaller drops, there might be a better\n        #   approach to spacing.\n        drop = Raindrop(self)\n        drop_width, drop_height = drop.rect.size\n\n        current_x, current_y = drop_width, drop_height\n        while current_y < (self.settings.screen_height - 2 * drop_height):\n            while current_x < (self.settings.screen_width - 2 * drop_width):\n                self._create_drop(current_x, current_y)\n                current_x += 2 * drop_width\n\n            # Finished a row; reset x value, and increment y value.\n            current_x = drop_width\n            current_y += 2 * drop_height\n\n    def _create_drop(self, x_position, y_position):\n        \"\"\"Create a drop and place it in the grid.\"\"\"\n        new_drop = Raindrop(self)\n        new_drop.y = y_position\n        new_drop.rect.x = x_position\n        new_drop.rect.y = y_position\n        self.raindrops.add(new_drop)\n\n    def _update_screen(self):\n        \"\"\"Update images on the screen, and flip to the new screen.\"\"\"\n        self.screen.fill(self.settings.bg_color)\n        self.raindrops.draw(self.screen)\n\n        pygame.display.flip()\n\n\nif __name__ == '__main__':\n    # Make a game instance, and run the game.\n    rd_game = RaindropsGame()\n    rd_game.run_game()\n","settings.py":"class Settings:\n    \"\"\"A class to store all settings for Alien Invasion.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game's settings.\"\"\"\n        # Screen settings\n        self.screen_width = 1200\n        self.screen_height = 800\n        self.bg_color = (230, 230, 230)\n\n        # Raindrop settings\n        self.raindrop_speed = 1.5"}},"13-4":{"ch":13,"entry":"raindrops_game.py","mode":"run","reason":null,"files":{"images/raindrop.png":{"b64":""},"raindrop.py":"import pygame\nfrom pygame.sprite import Sprite\n \nclass Raindrop(Sprite):\n    \"\"\"A class to represent a single raindrop.\"\"\"\n\n    def __init__(self, rd_game):\n        \"\"\"Initialize the raindrop and set its starting position.\"\"\"\n        super().__init__()\n        self.screen = rd_game.screen\n        self.settings = rd_game.settings\n\n        # Load the raindrop image and set its rect attribute.\n        #   Raindrop image from: https://commons.wikimedia.org/wiki/File:Antu_raindrop.svg\n        #   License: https://creativecommons.org/licenses/by-sa/3.0/deed.en\n        #   Modified size, and cropped.\n        self.image = pygame.image.load('images/raindrop.png')\n        self.rect = self.image.get_rect()\n\n        # Start each new raindrop near the top left of the screen.\n        self.rect.x = self.rect.width\n        self.rect.y = self.rect.height\n\n        # Store the raindrop's exact vertical position.\n        self.y = float(self.rect.y)\n\n    def check_disappeared(self):\n        \"\"\"Check if drop has disappeared off bottom of screen.\"\"\"\n        if self.rect.top > self.screen.get_rect().bottom:\n            return True\n        else:\n            return False\n\n    def update(self):\n        \"\"\"Move the raindrop down the screen.\"\"\"\n        self.y += self.settings.raindrop_speed\n        self.rect.y = self.y\n","raindrops_game.py":"import sys\n\nimport pygame\n\nfrom settings import Settings\nfrom raindrop import Raindrop\n\nclass RaindropsGame:\n    \"\"\"Overall class to manage game assets and behavior.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game, and create game resources.\"\"\"\n        pygame.init()\n        self.clock = pygame.time.Clock()\n        self.settings = Settings()\n\n        self.screen = pygame.display.set_mode(\n                (self.settings.screen_width, self.settings.screen_height))\n        pygame.display.set_caption(\"Raindrops\")\n\n        self.raindrops = pygame.sprite.Group()\n        self._create_drops()\n\n    def run_game(self):\n        \"\"\"Start the main loop for the game.\"\"\"\n        while True:\n            self._check_events()\n            self._update_raindrops()\n            self._update_screen()\n            self.clock.tick(60)\n\n    def _check_events(self):\n        \"\"\"Respond to keypresses and mouse events.\"\"\"\n        for event in pygame.event.get():\n            if event.type == pygame.QUIT:\n                sys.exit()\n            elif event.type == pygame.KEYDOWN:\n                self._check_keydown_events(event)\n\n    def _check_keydown_events(self, event):\n        \"\"\"Respond to keypresses.\"\"\"\n        if event.key == pygame.K_q:\n            sys.exit()\n\n    def _create_drops(self):\n        \"\"\"Create a sky full of raindrops.\"\"\"\n        # Create a drop and keep adding drops until there's no room left.\n        #   Spacing between drops is one drop width.\n        #   Note that the spacing here works reasonably for larger drops.\n        #   If you're working with smaller drops, there might be a better\n        #   approach to spacing.\n        drop = Raindrop(self)\n        drop_width, drop_height = drop.rect.size\n\n        current_x, current_y = drop_width, drop_height\n        while current_y < (self.settings.screen_height - 2 * drop_height):\n            while current_x < (self.settings.screen_width - 2 * drop_width):\n                self._create_drop(current_x, current_y)\n                current_x += 2 * drop_width\n\n            # Finished a row; reset x value, and increment y value.\n            current_x = drop_width\n            current_y += 2 * drop_height\n\n    def _create_drop(self, x_position, y_position):\n        \"\"\"Create a drop and place it in the grid.\"\"\"\n        new_drop = Raindrop(self)\n        new_drop.y = y_position\n        new_drop.rect.x = x_position\n        new_drop.rect.y = y_position\n        self.raindrops.add(new_drop)\n\n    def _create_new_row(self):\n        \"\"\"Create a new row of raindrops after a row disappears.\"\"\"\n        # Note: There are a number of ways to do this. This approach just\n        #   copies the code from _create_drops() that's used for a single\n        #   row of raindrops. This is simpler than trying to make \n        #   _create_drops() handle the full screen of raindrops, or a single\n        #   new row of raindrops.\n        drop = Raindrop(self)\n        drop_width, drop_height = drop.rect.size\n\n        current_x = drop_width\n        current_y = -1 * drop_height\n        while current_x < (self.settings.screen_width - 2 * drop_width):\n            self._create_drop(current_x, current_y)\n            current_x += 2 * drop_width\n\n    def _update_raindrops(self):\n        \"\"\"Update drop positions, and look for drops\n        that have disappeared.\n\n        Note: This solution isn't perfect; there's some space between periods\n          of rain. But it should give the idea of how to steadily create new\n          rows of drops. You can adjust the spacing to get a more uniform rain\n          effect, especially with smaller drops and randomized positions.\n        \"\"\"\n        self.raindrops.update()\n\n        # Assume we won't make new drops.\n        make_new_drops = False\n        for drop in self.raindrops.copy():\n            if drop.check_disappeared():\n                # Remove this drop, and we'll need to make new drops.\n                self.raindrops.remove(drop)\n                make_new_drops = True\n\n        # Make a new row of drops if needed.\n        if make_new_drops:\n            self._create_new_row()\n\n    def _update_screen(self):\n        \"\"\"Update images on the screen, and flip to the new screen.\"\"\"\n        self.screen.fill(self.settings.bg_color)\n        self.raindrops.draw(self.screen)\n\n        pygame.display.flip()\n\n\nif __name__ == '__main__':\n    # Make a game instance, and run the game.\n    rd_game = RaindropsGame()\n    rd_game.run_game()\n","settings.py":"class Settings:\n    \"\"\"A class to store all settings for Alien Invasion.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game's settings.\"\"\"\n        # Screen settings\n        self.screen_width = 1200\n        self.screen_height = 800\n        self.bg_color = (230, 230, 230)\n\n        # Raindrop settings\n        self.raindrop_speed = 1.5"}},"13-5":{"ch":13,"entry":"sideways_shooter.py","mode":"run","reason":null,"files":{"alien.py":"from random import randint\n\nimport pygame\nfrom pygame.sprite import Sprite\n \nclass Alien(Sprite):\n    \"\"\"A class to represent a single alien in the fleet.\"\"\"\n\n    def __init__(self, ss_game):\n        \"\"\"Initialize the alien and set its starting position.\"\"\"\n        super().__init__()\n        self.screen = ss_game.screen\n        self.settings = ss_game.settings\n\n        # Load the alien image and set its rect attribute.\n        self.image = pygame.image.load('images/alien_ship.png')\n        self.rect = self.image.get_rect()\n\n        # Start each new alien at a random position on the right side\n        #   of the screen.\n        self.rect.left = self.screen.get_rect().right\n        # The farthest down the screen we'll place the alien is the height\n        #   of the screen, minus the height of the alien.\n        alien_top_max = self.settings.screen_height - self.rect.height\n        self.rect.top = randint(0, alien_top_max)\n\n        # Store the alien's exact horizontal position.\n        self.x = float(self.rect.x)\n\n    def update(self):\n        \"\"\"Move the alien steadily to the left.\"\"\"\n        self.x -= self.settings.alien_speed\n        self.rect.x = self.x","bullet.py":"import pygame\nfrom pygame.sprite import Sprite\n \nclass Bullet(Sprite):\n    \"\"\"A class to manage bullets fired from the ship.\"\"\"\n\n    def __init__(self, ss_game):\n        \"\"\"Create a bullet object at the ship's current position.\"\"\"\n        super().__init__()\n        self.screen = ss_game.screen\n        self.settings = ss_game.settings\n        self.color = self.settings.bullet_color\n\n        # Create a bullet rect at (0, 0) and then set correct position.\n        self.rect = pygame.Rect(0, 0, self.settings.bullet_width,\n            self.settings.bullet_height)\n        self.rect.midright = ss_game.ship.rect.midright\n        \n        # Store the bullet's position as a decimal value.\n        self.x = float(self.rect.x)\n\n    def update(self):\n        \"\"\"Move the bullet across the screen.\"\"\"\n        # Update the decimal position of the bullet.\n        self.x += self.settings.bullet_speed\n        # Update the rect position.\n        self.rect.x = self.x\n\n    def draw_bullet(self):\n        \"\"\"Draw the bullet to the screen.\"\"\"\n        pygame.draw.rect(self.screen, self.color, self.rect)\n","images/GreenUFO_NoDmg.png":{"b64":""},"images/alien_ship.png":{"b64":""},"images/rocket_small.png":{"b64":""},"settings.py":"class Settings:\n    \"\"\"A class to store all settings for Sideways Shooter.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game's settings.\"\"\"\n        # Screen settings\n        self.screen_width = 1200\n        self.screen_height = 800\n        self.bg_color = (230, 230, 230)\n\n        # Ship settings\n        self.ship_speed = 3.0\n\n        # Bullet settings\n        self.bullet_speed = 6.0\n        self.bullet_width = 15\n        self.bullet_height = 3\n        self.bullet_color = (60, 60, 60)\n        self.bullets_allowed = 3\n\n        # Alien settings.\n        #  alien_frequency controls how often a new alien appear.s\n        #    Higher values -> more frequent aliens. Max = 1.0.\n        self.alien_frequency = 0.008\n        self.alien_speed = 1.5","ship.py":"import pygame\n \nclass Ship:\n    \"\"\"A class to manage the ship.\"\"\"\n \n    def __init__(self, ss_game):\n        \"\"\"Initialize the ship and set its starting position.\"\"\"\n        self.screen = ss_game.screen\n        self.settings = ss_game.settings\n        self.screen_rect = ss_game.screen.get_rect()\n\n        # Load the ship image and get its rect.\n        self.image = pygame.image.load('images/rocket_small.png')\n        self.rect = self.image.get_rect()\n\n        # Start each new ship at the center of the left side of the screen.\n        self.rect.midleft = self.screen_rect.midleft\n\n        # Store a decimal value for the ship's vertical position.\n        self.y = float(self.rect.y)\n\n        # Movement flags\n        self.moving_up = False\n        self.moving_down = False\n\n    def update(self):\n        \"\"\"Update the ship's position based on movement flags.\"\"\"\n        # Update the ship's y value, not the rect.\n        if self.moving_up and self.rect.top > 0:\n            self.y -= self.settings.ship_speed\n        if self.moving_down and self.rect.bottom < self.screen_rect.bottom:\n            self.y += self.settings.ship_speed\n\n        # Update rect object from self.y.\n        self.rect.y = self.y\n\n    def blitme(self):\n        \"\"\"Draw the ship at its current location.\"\"\"\n        self.screen.blit(self.image, self.rect)\n","sideways_shooter.py":"import sys\nfrom random import random\n\nimport pygame\n\nfrom settings import Settings\nfrom ship import Ship\nfrom bullet import Bullet\nfrom alien import Alien\n\nclass SidewaysShooter:\n    \"\"\"Overall class to manage game assets and behavior.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game, and create game resources.\"\"\"\n        pygame.init()\n        self.clock = pygame.time.Clock()\n        self.settings = Settings()\n\n        self.screen = pygame.display.set_mode(\n                (self.settings.screen_width, self.settings.screen_height))\n        pygame.display.set_caption(\"Sideways Shooter\")\n\n        self.ship = Ship(self)\n        self.bullets = pygame.sprite.Group()\n        self.aliens = pygame.sprite.Group()\n\n    def run_game(self):\n        \"\"\"Start the main loop for the game.\"\"\"\n        while True:\n            self._check_events()\n\n            # Consider creating a new alien.\n            self._create_alien()\n\n            self.ship.update()\n            self._update_bullets()\n            self.aliens.update()\n            self._update_screen()\n            self.clock.tick(60)\n\n    def _check_events(self):\n        \"\"\"Respond to keypresses and mouse events.\"\"\"\n        for event in pygame.event.get():\n            if event.type == pygame.QUIT:\n                sys.exit()\n            elif event.type == pygame.KEYDOWN:\n                self._check_keydown_events(event)\n            elif event.type == pygame.KEYUP:\n                self._check_keyup_events(event)\n\n    def _check_keydown_events(self, event):\n        \"\"\"Respond to keypresses.\"\"\"\n        if event.key == pygame.K_UP:\n            self.ship.moving_up = True\n        elif event.key == pygame.K_DOWN:\n            self.ship.moving_down = True\n        elif event.key == pygame.K_SPACE:\n            self._fire_bullet()\n        elif event.key == pygame.K_q:\n            sys.exit()\n\n    def _check_keyup_events(self, event):\n        \"\"\"Respond to key releases.\"\"\"\n        if event.key == pygame.K_UP:\n            self.ship.moving_up = False\n        elif event.key == pygame.K_DOWN:\n            self.ship.moving_down = False\n\n    def _fire_bullet(self):\n        \"\"\"Create a new bullet and add it to the bullets group.\"\"\"\n        if len(self.bullets) < self.settings.bullets_allowed:\n            new_bullet = Bullet(self)\n            self.bullets.add(new_bullet)\n\n    def _update_bullets(self):\n        \"\"\"Update position of bullets and get rid of old bullets.\"\"\"\n        # Update bullet positions.\n        self.bullets.update()\n\n        # Get rid of bullets that have disappeared.\n        for bullet in self.bullets.copy():\n            if bullet.rect.left >= self.screen.get_rect().right:\n                 self.bullets.remove(bullet)\n\n        self._check_bullet_alien_collisions()\n\n    def _check_bullet_alien_collisions(self):\n        \"\"\"Check whether any bullets have hit an alien.\"\"\"\n        collisions = pygame.sprite.groupcollide(\n                self.bullets, self.aliens, True, True)\n\n    def _create_alien(self):\n        \"\"\"Create an alien, if conditions are right.\"\"\"\n        if random() < self.settings.alien_frequency:\n            alien = Alien(self)\n            self.aliens.add(alien)\n\n    def _update_screen(self):\n        \"\"\"Update images on the screen, and flip to the new screen.\"\"\"\n        self.screen.fill(self.settings.bg_color)\n        self.ship.blitme()\n        for bullet in self.bullets.sprites():\n            bullet.draw_bullet()\n\n        self.aliens.draw(self.screen)\n\n        pygame.display.flip()\n\n\nif __name__ == '__main__':\n    # Make a game instance, and run the game.\n    ss_game = SidewaysShooter()\n    ss_game.run_game()"}},"13-6":{"ch":13,"entry":"sideways_shooter.py","mode":"run","reason":null,"files":{"alien.py":"from random import randint\n\nimport pygame\nfrom pygame.sprite import Sprite\n \nclass Alien(Sprite):\n    \"\"\"A class to represent a single alien in the fleet.\"\"\"\n\n    def __init__(self, ss_game):\n        \"\"\"Initialize the alien and set its starting position.\"\"\"\n        super().__init__()\n        self.screen = ss_game.screen\n        self.settings = ss_game.settings\n\n        # Load the alien image and set its rect attribute.\n        self.image = pygame.image.load('images/alien_ship.png')\n        self.rect = self.image.get_rect()\n\n        # Start each new alien at a random position on the right side\n        #   of the screen.\n        self.rect.left = self.screen.get_rect().right\n        # The farthest down the screen we'll place the alien is the height\n        #   of the screen, minus the height of the alien.\n        alien_top_max = self.settings.screen_height - self.rect.height\n        self.rect.top = randint(0, alien_top_max)\n\n        # Store the alien's exact horizontal position.\n        self.x = float(self.rect.x)\n\n    def update(self):\n        \"\"\"Move the alien steadily to the left.\"\"\"\n        self.x -= self.settings.alien_speed\n        self.rect.x = self.x","bullet.py":"import pygame\nfrom pygame.sprite import Sprite\n \nclass Bullet(Sprite):\n    \"\"\"A class to manage bullets fired from the ship.\"\"\"\n\n    def __init__(self, ss_game):\n        \"\"\"Create a bullet object at the ship's current position.\"\"\"\n        super().__init__()\n        self.screen = ss_game.screen\n        self.settings = ss_game.settings\n        self.color = self.settings.bullet_color\n\n        # Create a bullet rect at (0, 0) and then set correct position.\n        self.rect = pygame.Rect(0, 0, self.settings.bullet_width,\n            self.settings.bullet_height)\n        self.rect.midright = ss_game.ship.rect.midright\n        \n        # Store the bullet's position as a decimal value.\n        self.x = float(self.rect.x)\n\n    def update(self):\n        \"\"\"Move the bullet across the screen.\"\"\"\n        # Update the decimal position of the bullet.\n        self.x += self.settings.bullet_speed\n        # Update the rect position.\n        self.rect.x = self.x\n\n    def draw_bullet(self):\n        \"\"\"Draw the bullet to the screen.\"\"\"\n        pygame.draw.rect(self.screen, self.color, self.rect)\n","game_stats.py":"class GameStats:\n    \"\"\"Track statistics for the game.\"\"\"\n\n    def __init__(self, ss_game):\n        \"\"\"Initialize statistics.\"\"\"\n        self.settings = ss_game.settings\n        self.reset_stats()\n\n    def reset_stats(self):\n        \"\"\"Initialize statistics that can change during the game.\"\"\"\n        self.ships_left = self.settings.ship_limit","images/GreenUFO_NoDmg.png":{"b64":""},"images/alien_ship.png":{"b64":""},"images/rocket_small.png":{"b64":""},"settings.py":"class Settings:\n    \"\"\"A class to store all settings for Sideways Shooter.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game's settings.\"\"\"\n        # Screen settings\n        self.screen_width = 1200\n        self.screen_height = 800\n        self.bg_color = (230, 230, 230)\n\n        # Ship settings\n        self.ship_speed = 3.0\n        self.ship_limit = 3\n\n        # Bullet settings\n        self.bullet_speed = 6.0\n        self.bullet_width = 15\n        self.bullet_height = 3\n        self.bullet_color = (60, 60, 60)\n        self.bullets_allowed = 3\n\n        # Alien settings.\n        #  alien_frequency controls how often a new alien appear.s\n        #    Higher values -> more frequent aliens. Max = 1.0.\n        self.alien_frequency = 0.015\n        self.alien_speed = 6.0","ship.py":"import pygame\n \nclass Ship:\n    \"\"\"A class to manage the ship.\"\"\"\n \n    def __init__(self, ss_game):\n        \"\"\"Initialize the ship and set its starting position.\"\"\"\n        self.screen = ss_game.screen\n        self.settings = ss_game.settings\n        self.screen_rect = ss_game.screen.get_rect()\n\n        # Load the ship image and get its rect.\n        self.image = pygame.image.load('images/rocket_small.png')\n        self.rect = self.image.get_rect()\n\n        # Start each new ship at the center of the left side of the screen.\n        self.center_ship()\n\n        # Movement flags\n        self.moving_up = False\n        self.moving_down = False\n\n    def update(self):\n        \"\"\"Update the ship's position based on movement flags.\"\"\"\n        # Update the ship's y value, not the rect.\n        if self.moving_up and self.rect.top > 0:\n            self.y -= self.settings.ship_speed\n        if self.moving_down and self.rect.bottom < self.screen_rect.bottom:\n            self.y += self.settings.ship_speed\n\n        # Update rect object from self.y.\n        self.rect.y = self.y\n\n    def center_ship(self):\n        \"\"\"Center the ship on the left side of the screen.\"\"\"\n        self.rect.midleft = self.screen_rect.midleft\n\n        # Store a decimal value for the ship's vertical position.\n        self.y = float(self.rect.y)\n\n    def blitme(self):\n        \"\"\"Draw the ship at its current location.\"\"\"\n        self.screen.blit(self.image, self.rect)\n","sideways_shooter.py":"import sys\nfrom random import random\n\nimport pygame\n\nfrom settings import Settings\nfrom game_stats import GameStats\nfrom ship import Ship\nfrom bullet import Bullet\nfrom alien import Alien\n\nclass SidewaysShooter:\n    \"\"\"Overall class to manage game assets and behavior.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game, and create game resources.\"\"\"\n        pygame.init()\n        self.clock = pygame.time.Clock()\n        self.settings = Settings()\n\n        self.screen = pygame.display.set_mode(\n                (self.settings.screen_width, self.settings.screen_height))\n        pygame.display.set_caption(\"Sideways Shooter\")\n\n        # Create an instance to store game statistics.\n        self.stats = GameStats(self)\n\n        self.ship = Ship(self)\n        self.bullets = pygame.sprite.Group()\n        self.aliens = pygame.sprite.Group()\n\n        # Start game in an active state.\n        self.game_active = True\n\n    def run_game(self):\n        \"\"\"Start the main loop for the game.\"\"\"\n        while True:\n            self._check_events()\n\n            if self.game_active:\n                # Consider creating a new alien.\n                self._create_alien()\n\n                self.ship.update()\n                self._update_bullets()\n                self._update_aliens()\n            \n            self._update_screen()\n            self.clock.tick(60)\n\n    def _check_events(self):\n        \"\"\"Respond to keypresses and mouse events.\"\"\"\n        for event in pygame.event.get():\n            if event.type == pygame.QUIT:\n                sys.exit()\n            elif event.type == pygame.KEYDOWN:\n                self._check_keydown_events(event)\n            elif event.type == pygame.KEYUP:\n                self._check_keyup_events(event)\n\n    def _check_keydown_events(self, event):\n        \"\"\"Respond to keypresses.\"\"\"\n        if event.key == pygame.K_UP:\n            self.ship.moving_up = True\n        elif event.key == pygame.K_DOWN:\n            self.ship.moving_down = True\n        elif event.key == pygame.K_SPACE:\n            self._fire_bullet()\n        elif event.key == pygame.K_q:\n            sys.exit()\n\n    def _check_keyup_events(self, event):\n        \"\"\"Respond to key releases.\"\"\"\n        if event.key == pygame.K_UP:\n            self.ship.moving_up = False\n        elif event.key == pygame.K_DOWN:\n            self.ship.moving_down = False\n\n    def _fire_bullet(self):\n        \"\"\"Create a new bullet and add it to the bullets group.\"\"\"\n        if len(self.bullets) < self.settings.bullets_allowed:\n            new_bullet = Bullet(self)\n            self.bullets.add(new_bullet)\n\n    def _update_bullets(self):\n        \"\"\"Update position of bullets and get rid of old bullets.\"\"\"\n        # Update bullet positions.\n        self.bullets.update()\n\n        # Get rid of bullets that have disappeared.\n        for bullet in self.bullets.copy():\n            if bullet.rect.left >= self.screen.get_rect().right:\n                 self.bullets.remove(bullet)\n\n        self._check_bullet_alien_collisions()\n\n    def _check_bullet_alien_collisions(self):\n        \"\"\"Check whether any bullets have hit an alien.\"\"\"\n        collisions = pygame.sprite.groupcollide(\n                self.bullets, self.aliens, True, True)\n\n    def _create_alien(self):\n        \"\"\"Create an alien, if conditions are right.\"\"\"\n        if random() < self.settings.alien_frequency:\n            alien = Alien(self)\n            self.aliens.add(alien)\n\n    def _update_aliens(self):\n        \"\"\"Update alien positions, and look for collisions with ship.\"\"\"\n        self.aliens.update()\n\n        if pygame.sprite.spritecollideany(self.ship, self.aliens):\n            self._ship_hit()\n\n        # Look for aliens that have hit the left edge of the screen.\n        self._check_aliens_left_edge()\n\n    def _check_aliens_left_edge(self):\n        \"\"\"Respond to aliens that have hit left edge of the screen.\n        Treat this the same as the ship getting hit.\n        \"\"\"\n\n        for alien in self.aliens.sprites():\n            if alien.rect.left < 0:\n                self._ship_hit()\n                break\n\n    def _ship_hit(self):\n        \"\"\"Respond to an alien hitting the ship.\"\"\"\n        if self.stats.ships_left > 0:\n            # Decrement ships left.\n            self.stats.ships_left -= 1\n\n            # Get rid of any remaining aliens and bullets.\n            self.aliens.empty()\n            self.bullets.empty()\n\n            # Center the ship.\n            self.ship.center_ship()\n        else:\n            self.game_active = False\n\n    def _update_screen(self):\n        \"\"\"Update images on the screen, and flip to the new screen.\"\"\"\n        self.screen.fill(self.settings.bg_color)\n        self.ship.blitme()\n        for bullet in self.bullets.sprites():\n            bullet.draw_bullet()\n\n        self.aliens.draw(self.screen)\n\n        pygame.display.flip()\n\n\nif __name__ == '__main__':\n    # Make a game instance, and run the game.\n    ss_game = SidewaysShooter()\n    ss_game.run_game()"}}};
